          "ቦን ዝቅተኛው ውፍረት ያለው ፓርጹፊም (ኮማት መልኩት) ሲሆን ከዪሒዳ እስከ ኔሻማ ያሉትን ሁሉንም ከፍተኛ ብርሃናት የጎደለው ነው።",
